    "code": "// Segmented mode selection — active marks the current option\n<Group variant=\"secondary\" orientation=\"horizontal\" spacing=\"none\">\n  <Group.Button active={mode === \"write\"} onPress={() => setMode(\"write\")}>Write</Group.Button>\n  <Divider orientation=\"vertical\" />\n  <Group.Button active={mode === \"preview\"} onPress={() => setMode(\"preview\")}>Preview</Group.Button>\n</Group>\n\n// Icon-only toolbar — each action still needs an aria-label\n<Group variant=\"ghost\" orientation=\"horizontal\" spacing=\"xs\" aria-label=\"Text formatting\">\n  <Group.Button aria-label=\"Bold\"><FaBold /></Group.Button>\n  <Group.Button aria-label=\"Italic\"><FaItalic /></Group.Button>\n  <Group.Button aria-label=\"Underline\"><FaUnderline /></Group.Button>\n</Group>"
