    "code": "'use client';\n\nimport { useState } from 'react';\nimport { Group } from 'ui-lab-components/group';\n\nconst options = [\n  { value: 'all', label: 'All' },\n  { value: 'open', label: 'Open' },\n  { value: 'in-progress', label: 'In progress' },\n  { value: 'closed', label: 'Closed' },\n];\n\nfunction SegmentedFilter() {\n  const [status, setStatus] = useState('all');\n\n  return (\n    <Group spacing=\"none\" value={status} onChange={setStatus} aria-label=\"Filter by status\">\n      {options.map((option) => (\n        <Group.Button key={option.value} value={option.value}>{option.label}</Group.Button>\n      ))}\n    </Group>\n  );\n}\n\nexport function SegmentedFilterDemo() {\n  return <SegmentedFilter />;\n}\n",
